              expect(await board.locator('.card[data-id*="direct-review-1"], .card[data-id*="direct-review-2"], .card[data-id*="old-direct-review-2"]').count()).toBe(0);
              await capture(page, tag + "-direct-viewer", "[data-kanban-board] .card[data-id]");
